import { requestHub } from '../library/HubClient';
import { ensureProfileHub } from '../cli/commands/profile';
import { AgentReferenceSearchResultSchema } from '../types/design-library';
import {
  AGENT_SEARCH_DEFAULT_LIMIT,
  budgetAgentSearchResult,
} from '../services/profiles/profileSearch';

const AGENT_SEARCH_TIMEOUT_MS = 30_000;

export const findReferences = async ({
  accountId,
  query,
  sourceId,
  limit = AGENT_SEARCH_DEFAULT_LIMIT,
}: {
  accountId: string;
  query: string;
  sourceId?: string;
  limit?: number;
}) => {
  const hub = await ensureProfileHub({ isSourceSyncAllowed: false });
  return budgetAgentSearchResult(
    AgentReferenceSearchResultSchema.parse(
      await requestHub({
        hub,
        endpoint: '/profile/search',
        method: 'POST',
        body: { query, sourceId, limit, isAgentSearch: true },
        timeoutMs: AGENT_SEARCH_TIMEOUT_MS,
        expectedAccountId: accountId,
      }),
    ),
  );
};
